      "k9bd1d9ea4aa0": "KunThai roadmap",
      "k64ce09337c97": "KunThai should feel like one connected platform from the first minute. This onboarding prepares profile, preferences, and default entry points so the app feels intentional across every surface.",
      "k07c71eae506e": "KunThai support is not an emergency service. Contact the appropriate local emergency service when someone faces immediate harm.",
      "k328bb39c918d": "KunThai uses transparent Explore activity signals. AI-ready, without AI targeting yet.",
      "k4955eabca5a9": "KunThai will continue automatically when the connection improves.",
      "k1fe95917c190": "KunThai will create your owner role and default departments automatically. You can invite administrators, moderators, editors, customer support, and analysts after the Space exists.",
      "k4a7af038e328": "KunThai will surface important sign-in and account-change notices through trusted alert channels.",
