      "k86e0f21654a4": "KunThai يسألك في الوقت الحالي عن وجود ميزة تحتاج إلى الوصول إليها. لا ينبغي أن يؤدي رفض الإذن الاختياري إلى حظر الخدمات غير ذات الصلة.",
