      "k1fe95917c190": "سيقوم KunThai بإنشاء دور المالك والأقسام الافتراضية تلقائيًا. يمكنك دعوة المسؤولين والمشرفين والمحررين ودعم العملاء والمحللين بعد وجود Space.",
